.libPaths(c('UCEC_论文执行_v2_20261013/10_软件环境/R-library','UCEC_启动_20261013/11_版本与审查记录/软件环境/R-library',.libPaths()))
suppressPackageStartupMessages({library(Matrix);library(SingleCellExperiment);library(scater);library(scran);library(scDblFinder);library(celda);library(igraph);library(BiocNeighbors);library(BiocParallel)})
base<-'UCEC_论文执行_v2_20261013';sample<-commandArgs(TRUE)[1];dir<-file.path(base,'03_单细胞',sample);meta<-read.csv(file.path(base,'01_数据登记/单细胞样本.csv'),check.names=FALSE);dataset<-meta$dataset[match(sample,meta$sample)];set.seed(20261013)
if(file.exists(file.path(dir,'qc_sce.rds'))){cat('Checkpoint exists',sample,'\n');quit(status=0)}
x<-readRDS(file.path(dir,'raw_counts.rds'));qc<-read.csv(file.path(dir,'qc_raw.csv'));putative<-qc$detected_genes>=200 & qc$total_UMI>=500
robust_lower<-function(v,floor)max(floor,10^(median(log10(pmax(v[putative],1)))-3*mad(log10(pmax(v[putative],1)))))
loG<-round(robust_lower(qc$detected_genes,200));loU<-round(robust_lower(qc$total_UMI,500));mtU<-max(if(dataset=='GSE173682')20 else 10,min(if(dataset=='GSE173682')40 else 15,median(qc$percent_mt[putative])+3*mad(qc$percent_mt[putative])))
qc$passes_standard_QC<-qc$detected_genes>=loG & qc$total_UMI>=loU & qc$percent_mt<=mtU;thresholds<-data.frame(sample=sample,dataset=dataset,min_genes=loG,min_UMI=loU,max_MT=mtU,rationale='Three-MAD lower tails with floors; whole-cell mitochondrial upper at least20%, nucleus at least10%; retained higher thresholds when robust distribution warrants. No hard upper UMI/gene removal; doublets called separately.')
write.csv(thresholds,file.path(dir,'QC阈值.csv'),row.names=FALSE)
pdf(file.path(dir,'QC阈值依据.pdf'),width=10,height=7);par(mfrow=c(2,2));hist(log10(pmax(qc$total_UMI,1)),breaks=60,main=paste(sample,'UMIs'),xlab='log10 UMIs');abline(v=log10(loU),col='red',lwd=2);hist(log10(pmax(qc$detected_genes,1)),breaks=60,main='Detected genes',xlab='log10 genes');abline(v=log10(loG),col='red',lwd=2);hist(qc$percent_mt,breaks=60,main='Mitochondrial fraction',xlab='%');abline(v=mtU,col='red',lwd=2);plot(log10(pmax(qc$total_UMI,1)),log10(pmax(qc$detected_genes,1)),pch=16,cex=.15,col=ifelse(qc$passes_standard_QC,'grey50','red'),xlab='log10 UMI',ylab='log10 genes');dev.off()
y<-x[,qc$passes_standard_QC,drop=FALSE];cat(sample,'standardQC',ncol(x),'->',ncol(y),'threshold',loG,loU,mtU,'\n');flush.console()
sce<-SingleCellExperiment(list(counts=y));if(file.exists(file.path(dir,'doublet_calls.csv'))){dcalls<-read.csv(file.path(dir,'doublet_calls.csv'));idx<-match(colnames(sce),dcalls$barcode);stopifnot(!anyNA(idx));sce$scDblFinder.score<-dcalls$doublet_score[idx];sce$scDblFinder.class<-dcalls$doublet_class[idx]} else sce<-scDblFinder(sce,clusters=FALSE,nfeatures=2000,dims=20,BPPARAM=SerialParam());cat('Doublets',sum(sce$scDblFinder.class=='doublet'),'\n');flush.console();write.csv(data.frame(barcode=colnames(sce),doublet_score=sce$scDblFinder.score,doublet_class=sce$scDblFinder.class),file.path(dir,'doublet_calls.csv'),row.names=FALSE)
# Cell quality metadata is retained for all input barcodes.
qc$scDblFinder_score<-sce$scDblFinder.score[match(qc$barcode,colnames(sce))];qc$scDblFinder_class<-as.character(sce$scDblFinder.class[match(qc$barcode,colnames(sce))]);qc$passes_QC<-qc$passes_standard_QC & !is.na(qc$scDblFinder_class) & qc$scDblFinder_class=='singlet'
sce<-sce[,sce$scDblFinder.class=='singlet'];sce<-logNormCounts(sce);dec<-modelGeneVar(sce);hvg<-getTopHVGs(dec,n=2000);hvg<-hvg[!grepl('^MT-|^RPS|^RPL',hvg)];sce<-runPCA(sce,subset_row=hvg,ncomponents=20,BPPARAM=SerialParam());knn<-findKNN(reducedDim(sce,'PCA'),k=20,BPPARAM=SerialParam())$index;edges<-cbind(rep(seq_len(nrow(knn)),ncol(knn)),as.vector(knn));gr<-graph_from_edgelist(edges,directed=FALSE);gr<-simplify(gr);cl<-as.character(membership(cluster_louvain(gr)));names(cl)<-colnames(sce);sce$pre_cluster<-cl
saveRDS(sce,file.path(dir,'pre_decontX_sce.rds'),compress=FALSE)
# decontX estimates contamination from cell mixtures in filtered matrices; no empty droplet/background ground truth is available.
cat('decontX start',sample,ncol(sce),'cells',length(unique(cl)),'clusters\n');flush.console();dc<-decontX(counts(sce),z=as.integer(cl),seed=20261013,maxIter=100,verbose=FALSE);assay(sce,'decontXcounts')<-dc$decontXcounts;sce$decontX_contamination<-dc$contamination;rm(dc);gc()
# Keep both raw and corrected assays; standard-QC metadata tracks removed input cells.
qc$decontX_contamination<-sce$decontX_contamination[match(qc$barcode,colnames(sce))];write.csv(qc,file.path(dir,'QC全细胞追踪.csv'),row.names=FALSE)
# Corrected logarithmic expression drives annotation, raw counts remain available for sensitivity and pseudobulk.
sce_corrected<-SingleCellExperiment(list(counts=assay(sce,'decontXcounts')));sce_corrected<-logNormCounts(sce_corrected);assay(sce,'decontXlogcounts')<-logcounts(sce_corrected);rm(sce_corrected)
# Conventional within-sample PCA is sufficient for coarse compartments; no cross-donor integration is used for inference.
sce<-runUMAP(sce,dimred='PCA',n_neighbors=20,min_dist=.25,n_threads=2);colData(sce)$sample<-sample;colData(sce)$dataset<-dataset
saveRDS(sce,file.path(dir,'qc_sce.rds'),compress=FALSE);write.csv(data.frame(barcode=colnames(sce),sample=sample,pre_cluster=sce$pre_cluster,UMAP1=reducedDim(sce,'UMAP')[,1],UMAP2=reducedDim(sce,'UMAP')[,2],doublet_score=sce$scDblFinder.score,decontX_contamination=sce$decontX_contamination),file.path(dir,'细胞坐标与质控.csv'),row.names=FALSE)
write.csv(data.frame(sample=sample,dataset=dataset,raw=ncol(x),standard_QC=sum(qc$passes_standard_QC),doublets=sum(qc$scDblFinder_class=='doublet',na.rm=TRUE),singlets=ncol(sce),median_contamination=median(sce$decontX_contamination),fraction_contamination_gt_0.5=mean(sce$decontX_contamination>.5)),file.path(dir,'QC汇总.csv'),row.names=FALSE)
writeLines(capture.output(sessionInfo()),file.path(dir,'R_sessionInfo.txt'));cat('COMPLETE',sample,ncol(sce),'\n')
